const int ENA = 9;
const int IN1 = 7;
const int IN2 = 8;

void setup() {
  pinMode(ENA, OUTPUT);
  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
}

void loop() {
  // Maju, kecepatan sedang-tinggi
  digitalWrite(IN1, HIGH);
  digitalWrite(IN2, LOW);
  analogWrite(ENA, 200);
  delay(5000);

  // Berhenti sebentar sebelum membalik arah
  analogWrite(ENA, 0);
  delay(500);

  // Mundur, kecepatan lebih rendah
  digitalWrite(IN1, LOW);
  digitalWrite(IN2, HIGH);
  analogWrite(ENA, 100);
  delay(5000);

  analogWrite(ENA, 0);
  delay(500);
}

#include <Servo.h>

Servo servo;

void setup() {
  servo.attach(6);
}

void loop() {
  for (int sudut = 0; sudut <= 180; sudut += 5) {
    servo.write(sudut);
    delay(30);
  }
  for (int sudut = 180; sudut >= 0; sudut -= 5) {
    servo.write(sudut);
    delay(30);
  }
}

const int LED = 8;
unsigned long waktuSebelumnya = 0;
const unsigned long INTERVAL = 500;
bool keadaanLED = false;

void setup() {
  pinMode(LED, OUTPUT);
}

void loop() {
  unsigned long sekarang = millis();
  if (sekarang - waktuSebelumnya >= INTERVAL) {
    waktuSebelumnya = sekarang;
    keadaanLED = !keadaanLED;
    digitalWrite(LED, keadaanLED);
  }
  // kode lain tetap berjalan di sini tanpa terblokir
}

const int TOMBOL = 2;
const int LED = 8;
const unsigned long JEDA_DEBOUNCE = 200;  // milidetik

volatile bool keadaanLED = false;
volatile unsigned long waktuTerakhir = 0;

void ubahLED() {
  unsigned long sekarang = millis();
  // Abaikan pemicu yang datang terlalu cepat (bouncing)
  if (sekarang - waktuTerakhir >= JEDA_DEBOUNCE) {
    keadaanLED = !keadaanLED;
    waktuTerakhir = sekarang;
  }
}

void setup() {
  pinMode(LED, OUTPUT);
  pinMode(TOMBOL, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(TOMBOL), ubahLED, FALLING);
}

void loop() {
  digitalWrite(LED, keadaanLED);
}
